# Predicates fixed before run:
# P1 K4 ratio set over all start vertices, length-2 walks == {3/2,5/2,4}
# P2 B_q: -1 in group generated by gains; -1 not among gains for q>2; column quotients differ by -1
# P3 sum of all p-th roots =0 ; sum of roots of exact order p = -1
# P4 switching: strongly connected D (hypothesis tested), H=closed-walk gain group proper => spanning switching puts gains in H and hat D over H strongly connected
from fractions import Fraction as Fr
import cmath, random, itertools
# P1
g={ (a,b):0 for a in range(4) for b in range(4) if a!=b}; g[(0,1)]=1; g[(1,0)]=2
Fc={0:Fr(2),1:Fr(1,2),2:Fr(1,2)}
def F(w):
    if w[-1]!=w[0]: return Fr(1)
    return Fc[sum(g[(w[i],w[i+1])] for i in range(len(w)-1))%3]
R=set()
for x in range(4):
    for y in range(4):
        if y==x: continue
        for z in range(4):
            if z==y: continue
            w=(x,y,z); R.add(sum(F(w+(t,)) for t in range(4) if t!=z)/F(w))
print("P1",sorted(R), R=={Fr(3,2),Fr(5,2),Fr(4)})
# P2
for q in (2,4,6,8,10,12):
    h=q//2; gains={0,1,(1+h)%q}  # exponents of 1, zeta, -zeta
    grp={0}
    while True:
        n=grp|{(a+b)%q for a in grp for b in gains}
        if n==grp: break
        grp=n
    print("P2 q",q,"-1 in group",h in grp,"-1 among gains",h in gains,"quot diff", ((1+h)-0-(1-0))%q==h)
# P3
for p in (2,3,5,7):
    allr=sum(cmath.exp(2j*cmath.pi*k/p) for k in range(p)); prim=sum(cmath.exp(2j*cmath.pi*k/p) for k in range(1,p))
    print("P3",p,abs(allr)<1e-12, round(prim.real,9))
# P4
random.seed(1)
def sc(n,adj):
    def reach(a):
        s={0};st=[0]
        while st:
            u=st.pop()
            for v in a[u]:
                if v not in s:s.add(v);st.append(v)
        return len(s)==n
    rev=[[] for _ in range(n)]
    for u in range(n):
        for v in adj[u]: rev[v].append(u)
    return reach(adj) and reach(rev)
tot=qual=ok=0
for trial in range(3000):
    n=random.randint(2,6); q=random.choice([4,6,8,12]); sub=random.choice([d for d in range(1,q+1) if q%d==0])
    arcs={}
    for u in range(n):
        for v in random.sample(range(n),random.randint(1,min(3,n))):
            arcs[(u,v)]=random.randrange(0,q,sub)
    pot=[random.randrange(q) for _ in range(n)]
    arcs={(u,v):(a+pot[v]-pot[u])%q for (u,v),a in arcs.items()}
    tot+=1
    adj=[[v for (a,v) in arcs if a==u] for u in range(n)]
    if not sc(n,adj): continue
    # component of (0,0) in hat D
    seen={(0,0)};st=[(0,0)]
    while st:
        u,a=st.pop()
        for (s,v),e in arcs.items():
            if s==u and (v,(a+e)%q) not in seen: seen.add((v,(a+e)%q)); st.append((v,(a+e)%q))
    H={a for (u,a) in seen if u==0}
    if len(H)==q: continue
    qual+=1
    th={}
    for (u,a) in seen: th.setdefault(u,a)
    new={(u,v):(th[u]+e-th[v])%q for (u,v),e in arcs.items()}
    c1=all(e in H for e in new.values())
    N=len(H)*n
    hv=[(u,a) for u in range(n) for a in sorted(H)]; idx={x:i for i,x in enumerate(hv)}
    hadj=[[] for _ in hv]
    for (u,a) in hv:
        for (s,v),e in new.items():
            if s==u: hadj[idx[(u,a)]].append(idx[(v,(a+e)%q)])
    c2=c1 and sc(N,hadj)
    ok+=c1 and c2
print("P4 total",tot,"qualify",qual,"pass",ok)
